45	// SaveConfirmError means a node file's new content was written and atomically
46	// renamed into place, but the replacement could not be confirmed as a completed
47	// save: the file's directory could not be opened, or syncing that directory to
48	// disk returned an error. Both confirmations run in the save stage, after the
49	// rename, so this is a save failure even though the new file is already
50	// reachable — never a heartbeat content conflict, an illegal field, or stored
51	// data corruption: the file on disk is complete and well-formed, and it is left
52	// exactly as it landed (records already saved stay queryable; nothing is rolled
53	// back or deleted). A caller reports the batch as failed with zero new and zero
54	// duplicate counts, and the same batch can be resubmitted verbatim once the
55	// storage condition clears.
56	//
57	// Dir is the directory whose durability confirmation failed (nodes/ for a
58	// short node id, slots/ for a long one), and Op is the confirmation step that
59	// failed ("open" or "sync").
60	type SaveConfirmError struct {
61		Dir string
62		Op  string
63		Err error
64	}
65	
66	func (e *SaveConfirmError) Error() string {
67		switch e.Op {
68		case "open":
69			return fmt.Sprintf("save confirmation failed in directory %s: cannot open directory to confirm node-file replacement: %v", e.Dir, e.Err)
70		case "sync":
71			return fmt.Sprintf("save confirmation failed in directory %s: cannot sync directory to disk after node-file replacement: %v", e.Dir, e.Err)
72		default:
73			return fmt.Sprintf("save confirmation failed in directory %s: %v", e.Dir, e.Err)
74		}
75	}
76	
77	func (e *SaveConfirmError) Unwrap() error { return e.Err }
78	
79	// IsSaveConfirm reports whether err is (or wraps) a SaveConfirmError.
80	func IsSaveConfirm(err error) bool {
81		var se *SaveConfirmError
82		return errors.As(err, &se)
83	}
