85	// nodeFile is the on-disk layout for one node.
86	type nodeFile struct {
87		Format   string      `json:"format"`
88		Checksum string      `json:"checksum"`
89		Records  []Heartbeat `json:"records"`
90	}
91	
92	// Store persists heartbeats as per-node JSON files under a data directory.
93	// Multiple Store instances (in the same or different processes) may safely
94	// access the same directory concurrently: a flock on the directory lock file
95	// serialises writers and lets queries take a shared lock, so a query never
96	// observes a partially written batch.
97	//
98	// Node files live in two places chosen solely by the byte length of the node
99	// id:
100	//
101	//   - Short ids keep their file at nodes/hex(nodeID)+".json", exactly as
102	//     always; the file name itself decodes to the owning node id.
103	//   - Long ids (those whose hex name would exceed the local file-name limit)
104	//     keep their file at slots/<sha256(nodeID)>.json: a fixed-length content
105	//     name that never grows with the id. The hash is computed over the whole
106	//     id and only addresses the file — it never identifies the node — so a
107	//     slot is loaded for a specific queried id and every record in it must
108	//     declare that same id, the same ownership check a named hex file gets.
109	//     A different id whose well-formed file is found at this slot (a planted
110	//     foreign file) is refused as corruption rather than merged or read as
111	//     this node's telemetry.
112	type Store struct {
113		dir      string
114		nodesDir string
115		slotsDir string
116		lockPath string
117	}
118	
119	// OpenStore opens (and if needed creates) a data directory.
120	func OpenStore(dir string) (*Store, error) {
121		if err := os.MkdirAll(dir, 0o755); err != nil {
122			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
123		}
124		nodesDir := filepath.Join(dir, "nodes")
125		if err := os.MkdirAll(nodesDir, 0o755); err != nil {
126			return nil, fmt.Errorf("cannot create nodes directory %s: %w", nodesDir, err)
127		}
128		slotsDir := filepath.Join(dir, "slots")
129		if err := os.MkdirAll(slotsDir, 0o755); err != nil {
130			return nil, fmt.Errorf("cannot create slots directory %s: %w", slotsDir, err)
131		}
132		return &Store{
133			dir:      dir,
134			nodesDir: nodesDir,
135			slotsDir: slotsDir,
136			lockPath: filepath.Join(dir, "lock"),
137		}, nil
138	}
139	
140	// Dir returns the data directory path.
141	func (s *Store) Dir() string { return s.dir }
142	
143	// maxNodeFileNameBytes is the local file-system name limit the store targets:
144	// the base name of a short-id file is two hex characters per id byte plus the
145	// ".json" suffix, and may use the full limit — every such name was writable
146	// before long-id support existed, and keeping the limit at exactly this value
147	// means every id that previously saved still uses its original file (no
148	// rename, move or resubmit). Ids whose hex name would exceed the limit use a
149	// fixed-length slot name instead; the limit never rejects an id — it only
150	// selects where the file is placed.
151	const maxNodeFileNameBytes = 255
152	
153	// nodeLocation is the one on-disk file holding one node's records.
154	type nodeLocation struct {
155		path  string
156		owner string // the node id every record in the file must declare
157		named bool   // true: a legacy hex file whose name carries its owner; false: a hash-addressed slot whose owner is the queried id
158	}
159	
160	// nodeLocationFor maps a node id to its storage location. The mapping depends
161	// only on the exact id bytes — no trimming, whitespace handling or character
162	// replacement — so two ids are stored apart unless their bytes are identical:
163	// ids sharing a long prefix and differing at the end hash differently, and an
164	// id submitted literally or via equivalent JSON escapes decodes to the same
165	// bytes and maps to the same file. A short id's file name is its own hex,
166	// which reversibly carries its owner; a long id's slot name is the full hash
167	// of its bytes and carries no id text at all, so its owner is the queried id
168	// itself.
169	func (s *Store) nodeLocationFor(nodeID string) nodeLocation {
170		raw := []byte(nodeID)
171		hexName := hex.EncodeToString(raw) + ".json"
172		if len(hexName) <= maxNodeFileNameBytes {
173			return nodeLocation{
174				path:  filepath.Join(s.nodesDir, hexName),
175				owner: nodeID,
176				named: true,
177			}
178		}
179		sum := sha256.Sum256(raw)
180		return nodeLocation{
181			path:  filepath.Join(s.slotsDir, hex.EncodeToString(sum[:])+".json"),
182			owner: nodeID,
183		}
184	}
185	
186	// nodePath maps a node id to its per-node file. Short ids use a reversible hex
187	// file name; ids too long for a file name use a fixed-length content-addressed
188	// slot, so arbitrary-length legal Unicode ids never depend on a file name
189	// being able to hold them.
190	func (s *Store) nodePath(nodeID string) string {
191		return s.nodeLocationFor(nodeID).path
192	}
193	
194	// nodeOwnerFromPath recovers the node id a *short-id* store file belongs to
195	// from its file name: short-id files are named hex(nodeID)+".json", so the
196	// owner is exactly the string the base name decodes to. Slot file names are
197	// hashes that carry no node id; their owner is supplied by the caller (the id
198	// being queried), not inferred from the name.
199	func nodeOwnerFromPath(path string) (string, error) {
200		base := filepath.Base(path)
201		if !strings.HasSuffix(base, ".json") {
202			return "", fmt.Errorf("file name %q is not a per-node heartbeat file", base)
203		}
204		raw, err := hex.DecodeString(strings.TrimSuffix(base, ".json"))
205		if err != nil {
206			return "", fmt.Errorf("file name %q does not encode a node id: %w", base, err)
207		}
208		return string(raw), nil
209	}
210	
211	// lock acquires the directory lock. Exclusive for writes, shared for reads.
212	// The returned closure releases the lock.
213	func (s *Store) lock(exclusive bool) (func(), error) {
214		f, err := os.OpenFile(s.lockPath, os.O_RDWR|os.O_CREATE, 0o600)
215		if err != nil {
216			return nil, fmt.Errorf("cannot open lock file %s: %w", s.lockPath, err)
217		}
218		how := syscall.LOCK_SH
219		if exclusive {
220			how = syscall.LOCK_EX
221		}
222		if err := syscall.Flock(int(f.Fd()), how); err != nil {
223			f.Close()
224			return nil, fmt.Errorf("cannot acquire data lock: %w", err)
225		}
226		return func() {
227			syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
228			f.Close()
229		}, nil
230	}
231	
232	// checksumRecords returns a stable hash of the records. json.Marshal of a
233	// struct slice is deterministic for a given set of records.
234	func checksumRecords(records []Heartbeat) string {
235		data, _ := json.Marshal(records)
236		sum := sha256.Sum256(data)
237		return hex.EncodeToString(sum[:])
238	}
239	
240	// loadNodeFile reads and verifies the file at loc. A missing file means the
241	// node has no records (returns nil, nil). Any parse, checksum, ownership
242	// or structural failure is reported as a CorruptError.
243	//
244	// Ownership: the file belongs to exactly one node — loc.owner — and every
245	// record in it must declare that same node id. A file whose records name
246	// another node (for example another node's file copied over this one, format
247	// and checksum still intact) is not that node's telemetry: the whole file is
248	// refused as corrupt, no matter where the foreign record sits in the history
249	// and even if the latest record happens to name the right node.
250	//
251	// The two storage layouts prove ownership differently but enforce the exact
252	// same rule. A legacy file under nodes/ is named hex(owner), so its owner is
253	// decoded from the file name itself; that decoded id must also equal the id
254	// being queried. A slot file under slots/ has a hash for a name that reveals
255	// no node id, so its owner is the exact id whose slot this is — the full text
256	// the user queried or submitted, never a truncated or normalised form.
257	// Copying another node's complete file into a slot therefore fails just as
258	// copying it onto a legacy file name does.
259	//
260	// The file is decoded with the same strict rules as submit input: every
261	// telemetry field must be present, non-null and written once per record. A
262	// checksum that matches the zero-filled interpretation of a tampered record
263	// therefore cannot make a missing value look like real telemetry — the
264	// record is rejected before the checksum is consulted.
265	func loadNodeFile(loc nodeLocation) (*nodeFile, error) {
266		path := loc.path
267		data, err := os.ReadFile(path)
268		if os.IsNotExist(err) {
269			return nil, nil
270		}
271		if err != nil {
272			return nil, &CorruptError{Path: path, Err: err}
273		}
274		nf, err := decodeStrictNodeFile(data)
275		if err != nil {
276			return nil, &CorruptError{Path: path, Err: err}
277		}
278		if nf.Format != formatMarker {
279			return nil, &CorruptError{Path: path, Err: fmt.Errorf("unknown format marker %q", nf.Format)}
280		}
281		if err := validateStoredRecords(nf.Records); err != nil {
282			return nil, &CorruptError{Path: path, Err: err}
283		}
284		if got := checksumRecords(nf.Records); got != nf.Checksum {
285			return nil, &CorruptError{Path: path, Err: fmt.Errorf("checksum mismatch: stored %s, computed %s", nf.Checksum, got)}
286		}
287		owner := loc.owner
288		if loc.named {
289			namedOwner, err := nodeOwnerFromPath(path)
290			if err != nil {
291				return nil, &CorruptError{Path: path, Err: err}
292			}
293			// The queried id and the file name must name the same owner.
294			if namedOwner != owner {
295				return nil, &CorruptError{Path: path, Err: fmt.Errorf(
296					"file name encodes node %q, but it was loaded for node %q",
297					namedOwner, owner)}
298			}
299		}
300		for i, r := range nf.Records {
301			if r.NodeID != owner {
302				return nil, &CorruptError{Path: path, Err: fmt.Errorf(
303					"record %d: heartbeat declares node %q, but this file belongs to node %q",
304					i+1, r.NodeID, owner)}
305			}
306		}
307		return nf, nil
308	}
309	
310	// decodeStrictNodeFile parses the on-disk envelope without letting
311	// encoding/json defaults hide missing or duplicated data. The envelope has
312	// exactly three keys — format, checksum, records — each present, non-null and
313	// written once; the uniqueness judgement is the shared objectFields rule, so
314	// a Unicode-escaped spelling of the same key collides exactly as it does in a
315	// submitted heartbeat object. Every element of records is decoded with
316	// decodeStrictHeartbeatObject, so a missing, null or duplicated telemetry
317	// field is an error naming the record and field rather than a zero value.
318	// Whitespace and key ordering carry no meaning and never cause a failure.
319	func decodeStrictNodeFile(data []byte) (*nodeFile, error) {
320		dec := json.NewDecoder(bytes.NewReader(data))
321		tok, err := dec.Token()
322		if err != nil {
323			return nil, fmt.Errorf("invalid JSON: %w", err)
324		}
325		if d, ok := tok.(json.Delim); !ok || d != '{' {
326			return nil, fmt.Errorf("invalid JSON: file must be a JSON object")
327		}
328	
329		var (
330			format   string
331			checksum string
332			records  []json.RawMessage
333		)
334		fields := objectFields{}
335		for dec.More() {
336			keyTok, err := dec.Token()
337			if err != nil {
338				return nil, fmt.Errorf("invalid JSON: %w", err)
339			}
340			key, ok := keyTok.(string)
341			if !ok {
342				return nil, fmt.Errorf("invalid JSON: envelope field name must be a string")
343			}
344			var val json.RawMessage
345			if err := dec.Decode(&val); err != nil {
346				return nil, fmt.Errorf("invalid value for envelope field %q: %w", key, err)
347			}
348			if fields.check(key) {
349				return nil, fmt.Errorf("duplicate envelope field %q", key)
350			}
351			switch key {
352			case "format":
353				if bytes.Equal(val, []byte("null")) {
354					return nil, fmt.Errorf("envelope field %q must not be null", key)
355				}
356				if err := json.Unmarshal(val, &format); err != nil {
357					return nil, fmt.Errorf("format must be a string: %w", err)
358				}
359			case "checksum":
360				if bytes.Equal(val, []byte("null")) {
361					return nil, fmt.Errorf("envelope field %q must not be null", key)
362				}
363				if err := json.Unmarshal(val, &checksum); err != nil {
364					return nil, fmt.Errorf("checksum must be a string: %w", err)
365				}
366			case "records":
367				if bytes.Equal(val, []byte("null")) {
368					return nil, fmt.Errorf("envelope field %q must not be null", key)
369				}
370				if err := json.Unmarshal(val, &records); err != nil {
371					return nil, fmt.Errorf("records must be an array of heartbeat objects: %w", err)
372				}
373			default:
374				return nil, fmt.Errorf("unknown envelope field %q", key)
375			}
376		}
377		// Consume the closing brace.
378		if _, err := dec.Token(); err != nil {
379			return nil, fmt.Errorf("invalid JSON: %w", err)
380		}
381		// Nothing may follow the single envelope object.
382		if _, err := dec.Token(); err != io.EOF {
383			if err == nil {
384				return nil, fmt.Errorf("invalid JSON: unexpected data after the envelope object")
385			}
386			return nil, fmt.Errorf("invalid JSON: %w", err)
387		}
388	
389		if !fields.has("format") {
390			return nil, fmt.Errorf("missing required envelope field %q", "format")
391		}
392		if !fields.has("checksum") {
393			return nil, fmt.Errorf("missing required envelope field %q", "checksum")
394		}
395		if !fields.has("records") {
396			return nil, fmt.Errorf("missing required envelope field %q", "records")
397		}
398	
399		nf := &nodeFile{Format: format, Checksum: checksum, Records: make([]Heartbeat, 0, len(records))}
400		for i, raw := range records {
401			h, err := decodeStrictHeartbeatObject(raw)
402			if err != nil {
403				return nil, fmt.Errorf("record %d: %w", i+1, err)
404			}
405			nf.Records = append(nf.Records, h)
406		}
407		return nf, nil
408	}
409	
410	// validateStoredRecords checks the structural invariants of a strictly
411	// decoded record set: each record must satisfy the same field-value rules as
412	// submit input (one shared rule set — see checkHeartbeatValues), and records
413	// must be sorted by ascending seq with no duplicate seq. The stored-data
414	// wording and 1-based position prefix are kept by storedError. Position
415	// numbers are 1-based to match decoder errors.
416	func validateStoredRecords(records []Heartbeat) error {
417		for i, r := range records {
418			if e := checkHeartbeatValues(r); e != nil {
419				return e.storedError(i + 1)
420			}
421			if i > 0 && records[i-1].Seq >= r.Seq {
422				return fmt.Errorf("records not sorted by ascending seq at record %d", i+1)
423			}
424		}
425		return nil
426	}
427	
428	// writeNodeFile persists records atomically: a temp file in the same
429	// directory is fsynced and renamed over the target, so a crash never leaves
430	// a half-written file, and the containing directory is then opened and
431	// fsynced so the replacement itself is durable. A failure of that final
432	// directory confirmation (after the rename) is returned as *SaveConfirmError
433	// with the replaced file left intact.
434	//
435	// It is a package-level function variable rather than a plain func only so the
436	// persist stage can be deterministically failed from tests that exercise a
437	// real, mid-batch persistence failure (some node files already renamed into
438	// place before the failing one); production code always invokes the default
439	// implementation below and never reassigns it.
440	var writeNodeFile = func(path string, records []Heartbeat) error {
441		if records == nil {
442			records = []Heartbeat{}
443		}
444		nf := nodeFile{
445			Format:   formatMarker,
446			Checksum: checksumRecords(records),
447			Records:  records,
448		}
449		data, err := json.MarshalIndent(nf, "", "  ")
450		if err != nil {
451			return err
452		}
453		return writeFileAtomic(path, data)
454	}
455	
456	func writeFileAtomic(path string, data []byte) error {
457		dir := filepath.Dir(path)
458		tmp, err := os.CreateTemp(dir, ".tmp-*")
459		if err != nil {
460			return err
461		}
462		tmpName := tmp.Name()
463		if _, err := tmp.Write(data); err != nil {
464			tmp.Close()
465			os.Remove(tmpName)
466			return err
467		}
468		if err := tmp.Sync(); err != nil {
469			tmp.Close()
470			os.Remove(tmpName)
471			return err
472		}
473		if err := tmp.Close(); err != nil {
474			os.Remove(tmpName)
475			return err
476		}
477		if err := os.Rename(tmpName, path); err != nil {
478			os.Remove(tmpName)
479			return err
480		}
481		// The replacement is reachable but not yet confirmed durable: sync the
482		// containing directory. This is part of the save, and its failure is a save
483		// failure (see syncDirectoryDurably/SaveConfirmError); the renamed file is
484		// left intact either way.
485		return syncDirectoryDurably(dir)
486	}
487	
488	// syncDirectoryDurably opens dir and fsyncs it, confirming that a node file
489	// renamed into dir is durable. Both steps belong to the save stage: the
490	// directory may be unopenable (permissions, a dropped mount) or its fsync may
491	// return an I/O error, and either result means the replacement was not
492	// confirmed — although the rename already happened and the complete new file
493	// is reachable by name. Such a failure is therefore returned as
494	// *SaveConfirmError, never as corruption or a content error; the file on disk
495	// is well-formed and must not be rolled back.
496	//
497	// It is a package-level function variable for the same reason writeNodeFile
498	// is: the directory-sync step can be deterministically failed from tests that
499	// exercise a real, post-rename confirmation failure (the replacement already
500	// on disk when sync is refused). Production code always invokes the default
501	// implementation below and never reassigns it.
502	var syncDirectoryDurably = func(dir string) error {
503		d, err := os.Open(dir)
504		if err != nil {
505			return &SaveConfirmError{Dir: dir, Op: "open", Err: err}
506		}
507		syncErr := d.Sync()
508		d.Close()
509		if syncErr != nil {
510			return &SaveConfirmError{Dir: dir, Op: "sync", Err: syncErr}
511		}
512		return nil
513	}
514	
515	// mergeRecord applies the single dedup/conflict rule shared by both submit
516	// phases (records within the batch, and the batch against stored history): a
517	// record's identity is its node id and seq together, and known must contain
518	// only records of that same node. If known already holds the identity, the
519	// incoming record is a duplicate when Heartbeat.Equal says the content is
520	// identical — collection time compared as an instant, node id and version
521	// compared as-is — and a conflict when any field differs. A conflict is an
522	// error naming the node and seq and changes nothing; a duplicate leaves
523	// known untouched and reports dup. Otherwise the record is appended and
524	// returned in the updated slice.
525	func mergeRecord(known []Heartbeat, r Heartbeat) (updated []Heartbeat, dup bool, err error) {
526		for _, e := range known {
527			if e.Seq == r.Seq {
528				if !e.Equal(r) {
529					return nil, false, fmt.Errorf("conflicting record for node %q seq %d: content differs", r.NodeID, r.Seq)
530				}
531				return known, true, nil
532			}
533		}
534		return append(known, r), false, nil
535	}
536	
537	// Submit persists a batch of heartbeats. The whole batch is validated and
538	// checked for duplicates/conflicts against stored data (and within the batch)
539	// before anything is written: a single invalid or conflicting record fails
540	// the batch with no changes. Duplicates are counted, not written, and a node
541	// whose records are all duplicates of its saved history is not re-saved at
542	// all — only nodes that actually gained records are persisted. A
543	// successful return means the batch was durably persisted; a persistence
544	// failure is reported and previously queryable data is left intact.
545	func (s *Store) Submit(records []Heartbeat, receiveTime time.Time) (newCount, dupCount int, err error) {
546		if len(records) == 0 {
547			return 0, 0, fmt.Errorf("no heartbeat records provided")
548		}
549		for _, r := range records {
550			if err := ValidateHeartbeat(r, receiveTime); err != nil {
551				return 0, 0, fmt.Errorf("invalid heartbeat for node %q seq %d: %w", r.NodeID, r.Seq, err)
552			}
553		}
554	
555		unlock, err := s.lock(true)
556		if err != nil {
557			return 0, 0, err
558		}
559		defer unlock()
560	
561		// Deduplicate within the batch: same node+seq with equal content counts
562		// as a duplicate; same node+seq with differing content is a conflict.
563		merged := make(map[string][]Heartbeat)
564		for _, r := range records {
565			list, dup, err := mergeRecord(merged[r.NodeID], r)
566			if err != nil {
567				return 0, 0, err
568			}
569			if dup {
570				dupCount++
571				continue
572			}
573			merged[r.NodeID] = list
574		}
575	
576		// Merge with stored data per node, collecting new file contents. Every
577		// node's stored history is still loaded and checked (corruption or a
578		// conflict rejects the whole batch before anything is written), but a
579		// node whose records are all duplicates of what is already saved gains
580		// no record, so its file is left untouched: re-saving identical content
581		// would only turn a harmless retransmit into a write failure when the
582		// file's directory cannot be created or replaced.
583		type update struct {
584			loc     nodeLocation
585			records []Heartbeat
586		}
587		var updates []update
588		for nodeID, batch := range merged {
589			loc := s.nodeLocationFor(nodeID)
590			nf, err := loadNodeFile(loc)
591			if err != nil {
592				return 0, 0, err
593			}
594			existing := []Heartbeat{}
595			if nf != nil {
596				existing = nf.Records
597			}
598			nodeNew := 0
599			for _, r := range batch {
600				var dup bool
601				existing, dup, err = mergeRecord(existing, r)
602				if err != nil {
603					return 0, 0, err
604				}
605				if dup {
606					dupCount++
607				} else {
608					newCount++
609					nodeNew++
610				}
611			}
612			if nodeNew == 0 {
613				continue
614			}
615			sort.Slice(existing, func(i, j int) bool { return existing[i].Seq < existing[j].Seq })
616			updates = append(updates, update{loc: loc, records: existing})
617		}
618	
619		// Persist. All updates are appends to previously verified data, so a
620		// failure here leaves every previously queryable record intact. A failure
621		// can land after one node file's rename: the write itself completed but the
622		// directory durability confirmation (open/fsync) failed; that is still a
623		// save failure (SaveConfirmError) reported with zero counts, and the
624		// complete renamed file is left in place rather than rolled back.
625		for _, u := range updates {
626			if err := writeNodeFile(u.loc.path, u.records); err != nil {
627				return 0, 0, fmt.Errorf("failed to persist heartbeat batch: %w", err)
628			}
629		}
630		return newCount, dupCount, nil
631	}
632	
633	// HealthResult is the health judgement for one node based on real telemetry.
634	type HealthResult struct {
635		NodeID      string
636		Status      string // "online", "offline", "notelemetry"
637		Seq         int64
638		CollectedAt time.Time
639		Version     string
640		Height      int64
641		Missed      int64 // cumulative missed duties at the latest heartbeat
642		Findings    []string
643	
644		// Baseline-relative missed duties, populated only by HealthSince.
645		// BaselineSeq is the seq of the heartbeat the query was anchored to;
646		// BaselineMissed is the cumulative count at that heartbeat. When
647		// NewMissedKnown is false the cumulative counter went backwards
648		// somewhere between the baseline and the latest record, so the number of
649		// newly missed duties cannot be derived; Findings then reports the
650		// rollback. Missed always remains the latest cumulative count.
651		BaselineSeq    int64
652		BaselineMissed int64
653		NewMissed      int64
654		NewMissedKnown bool
655	}
656	
657	// rollbackFinding warns that the cumulative missed-duty counter decreased
658	// between two adjacent saved heartbeats (typically a node counter reset),
659	// which makes the endpoint difference unusable as the new-miss count.
660	const rollbackFinding = "累计漏签数回退"
661	
662	// Health judges a node from its latest telemetry (the record with the
663	// greatest seq). A node with no heartbeats returns Status "notelemetry". A
664	// query time earlier than the record's collection time is an error. Online
665	// status uses collection age against the query time: at most 60s is online
666	// (exactly 60s still online). Version skew and missed-duty rules follow the
667	// existing Evaluate rules.
668	func (s *Store) Health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int) (HealthResult, error) {
669		return s.health(nodeID, at, expectedVersion, toleratedMisses, 0, false)
670	}
671	
672	// HealthSince judges a node the same way Health does, but the missed-duty
673	// alarm is measured against a user-supplied baseline heartbeat instead of the
674	// cumulative counter alone. baselineSeq must be the seq (> 0) of a record
675	// already saved for the node: the latest heartbeat stays the record with the
676	// greatest seq, and new missed duties are the latest cumulative count minus
677	// the count at the baseline record. Only a strict excess over
678	// toleratedMisses alarms; equality does not.
679	//
680	// The baseline affects this query only: stored history is never modified.
681	// Seqs between the baseline and the latest may have gaps. If the cumulative
682	// count decreases between any two adjacent saved records in that interval the
683	// new count is reported as unknown (NewMissedKnown == false) and a rollback
684	// finding is emitted, even if the latest count later climbs back past the
685	// baseline; decreases before the baseline are irrelevant. A node without
686	// telemetry, an unknown baseline seq, or a baseline newer than the latest
687	// record is an error — no other record is substituted and the baseline count
688	// is never assumed to be zero.
689	func (s *Store) HealthSince(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64) (HealthResult, error) {
690		if baselineSeq <= 0 {
691			return HealthResult{}, fmt.Errorf("--missed-since-seq must be a positive integer, got %d", baselineSeq)
692		}
693		return s.health(nodeID, at, expectedVersion, toleratedMisses, baselineSeq, true)
694	}
695	
696	func (s *Store) health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64, useBaseline bool) (HealthResult, error) {
697		unlock, err := s.lock(false)
698		if err != nil {
699			return HealthResult{}, err
700		}
701		defer unlock()
702	
703		nf, err := loadNodeFile(s.nodeLocationFor(nodeID))
704		if err != nil {
705			return HealthResult{}, err
706		}
707		if nf == nil || len(nf.Records) == 0 {
708			if useBaseline {
709				return HealthResult{}, fmt.Errorf("node %q has no heartbeats; cannot use --missed-since-seq=%d as baseline", nodeID, baselineSeq)
710			}
711			return HealthResult{NodeID: nodeID, Status: "notelemetry", Findings: []string{"无遥测"}}, nil
712		}
713	
714		records := nf.Records // ascending seq, unique
715		latest := records[len(records)-1]
716	
717		if useBaseline {
718			if baselineSeq > latest.Seq {
719				return HealthResult{}, fmt.Errorf("--missed-since-seq=%d is newer than the latest heartbeat seq %d for node %q", baselineSeq, latest.Seq, nodeID)
720			}
721		}
722	
723		if at.Before(latest.CollectedAt) {
724			return HealthResult{}, fmt.Errorf("query time %s is earlier than collection time %s for node %q",
725				at.Format(time.RFC3339), latest.CollectedAt.Format(time.RFC3339), nodeID)
726		}
727	
728		age := at.Sub(latest.CollectedAt)
729		online := age <= onlineWindow
730	
731		result := HealthResult{
732			NodeID:      nodeID,
733			Status:      "online",
734			Seq:         latest.Seq,
735			CollectedAt: latest.CollectedAt,
736			Version:     latest.Version,
737			Height:      latest.Height,
738			Missed:      latest.Missed,
739		}
740		if !online {
741			result.Status = "offline"
742		}
743	
744		if !useBaseline {
745			// Cumulative judgement: the latest heartbeat's full cumulative counter
746			// must strictly exceed the tolerance. The counter is the int64 the node
747			// actually reported and saved — it is never narrowed to the native int
748			// width, which on a 32-bit system would reinterpret a counter above
749			// 2147483647 as negative or small and suppress the alarm. The strict
750			// rule itself lives once in missedExceedsTolerance (Evaluate is the
751			// demo's caller of it), as do the online/version rules.
752			result.Findings = livenessVersionFindings(online, latest.Version, expectedVersion)
753			if missedExceedsTolerance(latest.Missed, toleratedMisses) {
754				result.Findings = append(result.Findings, missedAboveToleranceFinding)
755			}
756			return result, nil
757		}
758	
759		// Baseline judgement: the online and version-skew findings come from the
760		// same shared rules as the cumulative query above; only the missed-duty
761		// statistic differs — it counts duties missed after the baseline record
762		// instead of the latest cumulative total.
763		findings := append([]string{}, livenessVersionFindings(online, latest.Version, expectedVersion)...)
764	
765		baselineIdx := -1
766		for i, r := range records {
767			if r.Seq == baselineSeq {
768				baselineIdx = i
769				break
770			}
771		}
772		if baselineIdx < 0 {
773			return HealthResult{}, fmt.Errorf("no saved heartbeat with seq %d for node %q; cannot use it as --missed-since-seq baseline", baselineSeq, nodeID)
774		}
775		baseline := records[baselineIdx]
776		result.BaselineSeq = baseline.Seq
777		result.BaselineMissed = baseline.Missed
778	
779		// Walk only saved records from the baseline up to the latest. Records are
780		// stored ascending by seq and seqs may legitimately have gaps, so any
781		// decrease between two adjacent saved records in this interval proves the
782		// cumulative counter reset somewhere in it; the endpoint difference alone
783		// must not be trusted even if the final count recovers.
784		rolledBack := false
785		for i := baselineIdx + 1; i < len(records); i++ {
786			if records[i].Missed < records[i-1].Missed {
787				rolledBack = true
788				break
789			}
790		}
791		if rolledBack {
792			result.NewMissedKnown = false
793			findings = append(findings, rollbackFinding)
794		} else {
795			result.NewMissedKnown = true
796			// No decrease was observed, so cumulative counts cannot have wrapped
797			// backwards within int64 range; the difference stays exact.
798			result.NewMissed = latest.Missed - baseline.Missed
799			if missedExceedsTolerance(result.NewMissed, toleratedMisses) {
800				findings = append(findings, missedAboveToleranceFinding)
801			}
802		}
803		result.Findings = findings
804		return result, nil
805	}
806	
807	// History returns all heartbeats for a node in ascending seq order, without
808	// duplicates. A node with no records returns an empty slice.
809	func (s *Store) History(nodeID string) ([]Heartbeat, error) {
810		unlock, err := s.lock(false)
811		if err != nil {
812			return nil, err
813		}
814		defer unlock()
815	
816		nf, err := loadNodeFile(s.nodeLocationFor(nodeID))
817		if err != nil {
818			return nil, err
819		}
820		if nf == nil {
821			return []Heartbeat{}, nil
822		}
823		return nf.Records, nil
824	}
825

