226		}
227		if got := hist[0].CollectedAt.Location(); got == nil {
228			t.Fatal("saved location lost")
229		}
230		if _, off := hist[0].CollectedAt.Zone(); off != 23*3600+59*60 {
231			t.Errorf("saved offset = %d, want %d", off, 23*3600+59*60)
232		}
233		// Re-read via the strict file decoder path by reopening the store.
234		reopened, err := OpenStore(store.Dir())
235		if err != nil {
236			t.Fatal(err)
237		}
238		hist2, err := reopened.History("edge")
239		if err != nil {
240			t.Fatal(err)
241		}
242		if !hist2[0].Equal(r) {
243			t.Errorf("round trip mismatch: %+v vs %+v", hist2[0], r)
244		}
