247	// TestParseHeartbeatsTextOffsetRejectsWholeBatchJSON pins the JSON-side
248	// atomicity: a leading valid record must not survive when a later record
249	// carries an out-of-range offset (ParseHeartbeats returns no partial records).
250	func TestParseHeartbeatsTextOffsetRejectsWholeBatchJSON(t *testing.T) {
251		input := `[
252		  {"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0},
253		  {"node":"n2","seq":1,"collected_at":"2026-10-01T11:59:00+00:60","version":"1.0","height":1,"missed":0}
254		]`
255		records, err := ParseHeartbeats([]byte(input), testBase.Add(48*time.Hour))
256		if err == nil {
257			t.Fatal("batch with folded offset must be rejected")
258		}
259		if records != nil {
260			t.Errorf("ParseHeartbeats must return no partial records, got %v", records)
261		}
262		if !strings.Contains(err.Error(), "record 2") || !strings.Contains(err.Error(), "collected_at") {
263			t.Errorf("error must locate record 2 and collected_at, got %v", err)
264		}
265	}
