267	// TestStoredFoldedOffsetFileIsCorrupt forges a node file whose raw JSON
268	// contains an out-of-range offset that decodes to a folded instant, with a
269	// checksum matching the folded interpretation. The read path must reject it as
270	// corruption naming the record and field, exactly like any other invalid
271	// stored value.
272	func TestStoredFoldedOffsetFileIsCorrupt(t *testing.T) {
273		dir := t.TempDir()
274		store, err := OpenStore(dir)
275		if err != nil {
276			t.Fatal(err)
277		}
278		path := store.nodePath("n1")
279		tamperedFile(t, path, `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00+00:60","version":"1.0","height":100,"missed":0}]`)
280	
281		_, err = loadNodeFileFor(store, "n1")
282		if err == nil || !IsCorrupt(err) {
283			t.Fatalf("folded-offset stored file must be corruption, got %v", err)
284		}
285		msg := err.Error()
286		if !strings.Contains(msg, filepath.Base(path)) || !strings.Contains(msg, "record 1") ||
287			!strings.Contains(msg, "collected_at") || !strings.Contains(msg, "00-59") {
288			t.Errorf("corruption error must name file, record 1 and the offset rule, got %v", err)
289		}
290		if _, err := store.Health("n1", testBase.Add(48*time.Hour), "1.0", 0); err == nil || !IsCorrupt(err) {
291			t.Errorf("health must refuse folded-offset data, got %v", err)
292		}
293		if _, err := store.History("n1"); err == nil || !IsCorrupt(err) {
294			t.Errorf("history must refuse folded-offset data, got %v", err)
295		}
296	}
297	
298	// TestStoredOutOfRangeHourOffsetFileIsCorrupt covers the hour bound on disk:
299	// a hand-written file carrying +24:00 (which time.Parse accepts) has to be
300	// rejected while reading, not folded or accepted.
301	func TestStoredOutOfRangeHourOffsetFileIsCorrupt(t *testing.T) {
302		dir := t.TempDir()
303		store, err := OpenStore(dir)
304		if err != nil {
305			t.Fatal(err)
306		}
307		path := store.nodePath("n1")
308		tamperedFile(t, path, `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00+24:00","version":"1.0","height":100,"missed":0}]`)
309	
310		_, err = loadNodeFileFor(store, "n1")
311		if err == nil || !IsCorrupt(err) {
312			t.Fatalf("+24:00 stored file must be corruption, got %v", err)
313		}
314		if !strings.Contains(err.Error(), "record 1") || !strings.Contains(err.Error(), "collected_at") {
315			t.Errorf("corruption error must name record 1 and collected_at, got %v", err)
316		}
317	}
