358		zeros := []Heartbeat{hb("z", 1, receive.Add(-time.Second), "1.0", 0, 0)}
359		// Large legal integers must survive exactly.
360		const big = int64(9223372036854775807)
361		bigs := []Heartbeat{hb("big", 1, receive.Add(-time.Second), "1.0", big, big-2)}
362		if _, _, err := store.Submit(append(append([]Heartbeat{}, zeros...), bigs...), receive); err != nil {
