405	// strictChecksum replicates the store's checksum over the canonical JSON of a
406	// single record slice, so a test can forge a checksum matching a tampered
407	// interpretation. canonicalJSON must be the store's marshaled record form.
408	func strictChecksum(canonicalJSON string) string {
409		sum := sha256.Sum256([]byte(canonicalJSON))
410		return hex.EncodeToString(sum[:])
411	}
412	
413	// envelope wraps a raw records array in a well-formed store file.
414	func envelope(checksum, recordsJSON string) string {
415		return `{"format":"edgefleet-heartbeats-v1","checksum":"` + checksum + `","records":` + recordsJSON + `}`
416	}
