684	func TestCLISubmitRejectsUnpairedSurrogate(t *testing.T) {
685		dir := t.TempDir()
686		batch := `[{"node":"val-\uD83D","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}]`
687		out, errOut, code := runCLI(t, dir, batch,
688			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
689		if code == 0 {
690			t.Errorf("submit with an unpaired surrogate must exit non-zero; stdout=%q", out)
691		}
692		if !strings.Contains(errOut, "record 1") || !strings.Contains(errOut, "node") {
693			t.Errorf("stderr must name the failing record and the node field, got %q", errOut)
694		}
695		// The batch is refused before the store is touched: no node file exists.
696		files, err := os.ReadDir(filepath.Join(dir, "nodes"))
697		if err != nil && !os.IsNotExist(err) {
698			t.Fatal(err)
699		}
700		if len(files) != 0 {
701			t.Errorf("no node file may be created, found %d", len(files))
702		}
703	}
704	
705	// TestCLISubmitValidUnicodeNodeRoundTrip checks the legal cases keep working
706	// end to end: a literal "�" is a valid character the user typed, an emoji
707	// written as a surrogate-pair escape is the same node as its literal form,
708	// and both are queryable by their original id.
709	func TestCLISubmitValidUnicodeNodeRoundTrip(t *testing.T) {
710		dir := t.TempDir()
711	
712		// Literal replacement character: a legal id, accepted as-is.
713		out, _, code := runCLI(t, dir,
714			`[{"node":"val-�","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}]`,
715			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
716		if code != 0 || !strings.Contains(out, "new=1") {
717			t.Fatalf("literal replacement char must be accepted: code=%d out=%q", code, out)
718		}
719	
720		// The same text as a � escape is the same node: duplicate, not new.
721		out, _, code = runCLI(t, dir,
722			`[{"node":"val-\uFFFD","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}]`,
723			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
724		if code != 0 || !strings.Contains(out, "new=0 duplicate=1") {
725			t.Errorf("escaped form of the same id must be a duplicate: code=%d out=%q", code, out)
726		}
727	
728		// An emoji written as a surrogate-pair escape is stored under the emoji.
729		out, _, code = runCLI(t, dir,
730			`[{"node":"val-\uD83D\uDE00","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":2,"missed":0}]`,
731			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
732		if code != 0 || !strings.Contains(out, "new=1") {
733			t.Fatalf("surrogate-pair escape must be accepted: code=%d out=%q", code, out)
734		}
735	
736		// Both nodes are queryable by their original ids.
737		out, _, code = runCLI(t, dir, "",
738			"heartbeat", "history", "--data-dir", dir, "--node", "val-�")
739		if code != 0 || !strings.Contains(out, "node=val-� seq=1") {
740			t.Errorf("history for literal replacement char id: code=%d out=%q", code, out)
741		}
742		out, _, code = runCLI(t, dir, "",
743			"heartbeat", "history", "--data-dir", dir, "--node", "val-😀")
744		if code != 0 || !strings.Contains(out, "node=val-😀 seq=1") {
745			t.Errorf("history for emoji id: code=%d out=%q", code, out)
746		}
747	}
748	
749	// submit runs one submit command and returns its full result for inspection.
750	func submit(t *testing.T, dir, json string) (string, string, int) {
751		t.Helper()
752		return runCLI(t, dir, json,
753			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
754	}
755	
756	// history runs the history command for one node.
757	func historyCLI(t *testing.T, dir, node string) (string, string, int) {
758		t.Helper()
759		return runCLI(t, dir, "",
760			"heartbeat", "history", "--data-dir", dir, "--node", node)
761	}
762	
763	// historyLines returns the non-empty history lines for a node.
764	func historyLines(t *testing.T, dir, node string) []string {
765		t.Helper()
766		out, errOut, code := historyCLI(t, dir, node)
767		if code != 0 {
768			t.Fatalf("history for %q exited %d: stderr=%q", node, code, errOut)
769		}
770		return outputLines(out)
771	}
772	
773	// TestCLISubmitMixedBatchCountsNewAndDuplicate drives the example rule end to
774	// end: a batch may mix records already saved, exact repeats within the same
775	// batch, and new records for other nodes. new counts only records genuinely
776	// added this time; duplicate counts every input record that added nothing.
777	// The same seq used by different nodes is never deduplicated across nodes.
778	func TestCLISubmitMixedBatchCountsNewAndDuplicate(t *testing.T) {
779		dir := t.TempDir()
780	
781		// 甲 already has seq 1 saved.
782		submitBatch(t, dir, `[
783		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}
784		]`)
785	
786		// Batch: 甲 seq1 again verbatim (duplicate against history), 甲 seq2 twice
787		// identical (one new, one duplicate within the batch), 乙 seq2 (new). The
788		// two nodes share seq 2 but stay distinct records.
789		out, errOut, code := submit(t, dir, `[
790		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0},
791		  {"node":"甲","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":101,"missed":0},
792		  {"node":"甲","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":101,"missed":0},
793		  {"node":"乙","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.26.0","height":201,"missed":2}
794		]`)
795		if code != 0 {
796			t.Fatalf("mixed batch must succeed, exit=%d stderr=%q", code, errOut)
797		}
798		if errOut != "" {
799			t.Errorf("a successful submit must leave stderr empty, got %q", errOut)
800		}
801		if strings.TrimRight(out, "\n") != "submitted: new=2 duplicate=2" {
802			t.Errorf("stdout = %q, want submitted: new=2 duplicate=2", out)
803		}
804	
805		// 甲 history: exactly seq 1 and 2, ascending, original seq-1 telemetry
806		// untouched and seq-2 content as submitted.
807		jia := historyLines(t, dir, "甲")
808		if len(jia) != 2 {
809			t.Fatalf("甲 history = %q, want exactly two records", jia)
810		}
811		want1 := "node=甲 seq=1 collected_at=2026-10-01T11:59:00Z version=1.26.0 height=100 missed=0"
812		want2 := "node=甲 seq=2 collected_at=2026-10-01T11:59:30Z version=1.26.0 height=101 missed=0"
813		if jia[0] != want1 {
814			t.Errorf("甲 first line = %q, want %q", jia[0], want1)
815		}
816		if jia[1] != want2 {
817			t.Errorf("甲 second line = %q, want %q", jia[1], want2)
818		}
819	
820		// 乙 has only its own seq 2; same seq number as 甲 did not dedup.
821		yi := historyLines(t, dir, "乙")
822		if len(yi) != 1 {
823			t.Fatalf("乙 history = %q, want exactly one record", yi)
824		}
825		wantYi := "node=乙 seq=2 collected_at=2026-10-01T11:59:30Z version=1.26.0 height=201 missed=2"
826		if yi[0] != wantYi {
827			t.Errorf("乙 line = %q, want %q", yi[0], wantYi)
828		}
829	}
830	
831	// TestCLISubmitSameInstantDifferentOffsetIsDuplicate pins the time semantics
832	// of "identical content": the same instant written with another timezone
833	// offset is a duplicate, both within a batch and against saved history.
834	func TestCLISubmitSameInstantDifferentOffsetIsDuplicate(t *testing.T) {
835		dir := t.TempDir()
836	
837		// 11:00:00Z is the same instant as 19:00:00+08:00.
838		out, errOut, code := submit(t, dir, `[
839		  {"node":"n1","seq":1,"collected_at":"2026-10-01T11:00:00Z","version":"1.0","height":10,"missed":0},
840		  {"node":"n1","seq":1,"collected_at":"2026-10-01T19:00:00+08:00","version":"1.0","height":10,"missed":0}
841		]`)
842		if code != 0 {
843			t.Fatalf("same-instant pair inside one batch must be accepted: exit=%d stderr=%q", code, errOut)
844		}
845		if strings.TrimRight(out, "\n") != "submitted: new=1 duplicate=1" {
846			t.Errorf("in-batch timezone-equal record: stdout=%q, want new=1 duplicate=1", out)
847		}
848	
849		// Against saved history, the offset-spelled repeat is still a duplicate.
850		out, errOut, code = submit(t, dir, `[
851		  {"node":"n1","seq":1,"collected_at":"2026-10-01T07:00:00-04:00","version":"1.0","height":10,"missed":0}
852		]`)
853		if code != 0 {
854			t.Fatalf("same-instant resubmit must succeed: exit=%d stderr=%q", code, errOut)
855		}
856		if errOut != "" {
857			t.Errorf("duplicate resubmit must leave stderr empty, got %q", errOut)
858		}
859		if strings.TrimRight(out, "\n") != "submitted: new=0 duplicate=1" {
860			t.Errorf("stdout=%q, want new=0 duplicate=1", out)
861		}
862	
863		lines := historyLines(t, dir, "n1")
864		if len(lines) != 1 {
865			t.Fatalf("history = %q, want the one record with no extra copy", lines)
866		}
867	}
868	
869	// TestCLISubmitContentDifferencesConflictAgainstHistory covers every field
870	// that makes a same-node/same-seq record a conflict rather than a duplicate:
871	// version, height, cumulative missed, and the collection instant (including
872	// equal wall-clock text with a different offset, which is a different
873	// instant). Nothing is overwritten and no last-write-wins occurs.
874	func TestCLISubmitContentDifferencesConflictAgainstHistory(t *testing.T) {
875		const base = `{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}`
876		cases := []struct {
877			name string
878			// incoming is the conflicting record, same node+seq as the saved one.
879			incoming string
880		}{
881			{"version differs",
882				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.27.0","height":100,"missed":0}`},
883			{"height differs",
884				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":101,"missed":0}`},
885			{"missed differs",
886				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":1}`},
887			{"collected instant differs",
888				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:58:00Z","version":"1.26.0","height":100,"missed":0}`},
889			{"same wall clock text, different offset is a different instant",
890				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00+08:00","version":"1.26.0","height":100,"missed":0}`},
891		}
892		for _, tc := range cases {
893			t.Run(tc.name, func(t *testing.T) {
894				dir := t.TempDir()
895				// Each subtest gets its own data directory, so one fixed node id
896				// carrying the saved seq-2 baseline is enough.
897				const node = "node"
898				submitBatch(t, dir, "["+fmt.Sprintf(base, node)+"]")
899				before := historyLines(t, dir, node)
900	
901				out, errOut, code := submit(t, dir, "["+fmt.Sprintf(tc.incoming, node)+"]")
902				if code == 0 {
903					t.Fatalf("conflicting record must fail non-zero; stdout=%q", out)
904				}
905				// The error names the node and the seq, and goes to stderr.
906				for _, want := range []string{"error:", "conflict", node, "seq 2"} {
907					if !strings.Contains(errOut, want) {
908						t.Errorf("stderr %q must contain %q", errOut, want)
909					}
910				}
911				// No success line or counters on stdout.
912				if strings.Contains(out, "submitted") || strings.Contains(out, "new=") {
913					t.Errorf("rejected batch must not print success counts, stdout=%q", out)
914				}
915				// The original telemetry is intact: not replaced by the incoming
916				// content, not counted as a duplicate.
917				after := historyLines(t, dir, node)
918				if len(after) != 1 || after[0] != before[0] {
919					t.Errorf("history changed after conflict:\nbefore=%q\nafter =%q", before, after)
920				}
921			})
922		}
923	}
924	
925	// TestCLISubmitConflictWithinBatchRejectsEverything checks the first conflict
926	// condition: two records of the same node+seq with differing content inside
927	// one batch fail the whole batch. Legal records for other nodes — whether
928	// they appear before or after the conflicting pair — must not survive, and a
929	// pre-existing node touched by a legal record in the same batch stays as it
930	// was before the submit.
931	func TestCLISubmitConflictWithinBatchRejectsEverything(t *testing.T) {
932		dir := t.TempDir()
933		// Existing node 旧 with seq 1 already saved.
934		submitBatch(t, dir, `[
935		  {"node":"旧","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":10,"missed":0}
936		]`)
937		oldBefore := readNodeFile(t, dir, "旧")
938	
939		// Batch layout: legal record for a brand-new node 新, then a legal seq-2
940		// for the existing node, then the in-batch conflict on 甲 seq 1, then
941		// another legal new-node record. None of the legal ones may be saved.
942		batch := `[
943		  {"node":"新","seq":1,"collected_at":"2026-10-01T11:59:10Z","version":"1.0","height":20,"missed":0},
944		  {"node":"旧","seq":2,"collected_at":"2026-10-01T11:59:20Z","version":"1.0","height":11,"missed":0},
945		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:30Z","version":"1.0","height":100,"missed":0},
946		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:30Z","version":"2.0","height":100,"missed":0},
947		  {"node":"丙","seq":1,"collected_at":"2026-10-01T11:59:40Z","version":"1.0","height":30,"missed":0}
948		]`
949		out, errOut, code := submit(t, dir, batch)
950		if code == 0 {
951			t.Fatalf("in-batch conflict must fail non-zero; stdout=%q", out)
952		}
953		for _, want := range []string{"error:", "conflict", "甲", "seq 1"} {
954			if !strings.Contains(errOut, want) {
955				t.Errorf("stderr %q must contain %q", errOut, want)
956			}
957		}
958		if strings.Contains(out, "submitted") || strings.Contains(out, "new=") {
959			t.Errorf("rejected batch must print no success counts, stdout=%q", out)
960		}
961	
962		// Existing node untouched even though its legal record came first.
963		if got := readNodeFile(t, dir, "旧"); got != oldBefore {
964			t.Errorf("existing node file was modified by the rejected batch")
965		}
966		// Brand-new nodes in the batch must have no history at all.
967		for _, node := range []string{"新", "甲", "丙"} {
968			out, errOut, code := historyCLI(t, dir, node)
969			if code != 0 {
970				t.Fatalf("history query after rejected batch must itself work for %q: %d %q", node, code, errOut)
971			}
972			if strings.TrimRight(out, "\n") != "node="+node+" no heartbeats" {
973				t.Errorf("node %q must have no records after rejected batch, got %q", node, out)
974			}
975			if _, err := os.Stat(nodeFileHexPath(dir, node)); !os.IsNotExist(err) {
976				t.Errorf("no file may be created for node %q, stat err=%v", node, err)
977			}
978		}
979	}
980	
981	// TestCLISubmitConflictWithSavedHistoryRejectsWholeBatch checks the second
982	// conflict condition: a batch record whose node+seq already exists with
983	// different content fails the batch, including legal records placed before
984	// it. After the failure the store keeps accepting ordinary batches, and all
985	// previously saved content stays queryable.
986	func TestCLISubmitConflictWithSavedHistoryRejectsWholeBatch(t *testing.T) {
987		dir := t.TempDir()
988		// 甲 already saved seq 1 with specific telemetry.
989		submitBatch(t, dir, `[
990		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}
991		]`)
992		jiaBefore := readNodeFile(t, dir, "甲")
993	
994		// Legal record for a new node FIRST, then the conflict against saved
995		// history, then another legal new-node record.
996		batch := `[
997		  {"node":"乙","seq":1,"collected_at":"2026-10-01T11:59:10Z","version":"1.0","height":200,"missed":1},
998		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"9.9.9","height":100,"missed":0},
999		  {"node":"丙","seq":1,"collected_at":"2026-10-01T11:59:20Z","version":"1.0","height":300,"missed":2}
1000		]`
1001		out, errOut, code := submit(t, dir, batch)
1002		if code == 0 {
1003			t.Fatalf("history conflict must fail non-zero; stdout=%q", out)
1004		}
1005		for _, want := range []string{"error:", "conflict", "甲", "seq 1"} {
1006			if !strings.Contains(errOut, want) {
1007				t.Errorf("stderr %q must contain %q", errOut, want)
1008			}
1009		}
1010		if strings.Contains(out, "submitted") || strings.Contains(out, "new=") {
1011			t.Errorf("rejected batch must print no success counts, stdout=%q", out)
1012		}
1013	
1014		// 甲 history is byte-identical to before the attempt.
1015		if got := readNodeFile(t, dir, "甲"); got != jiaBefore {
1016			t.Errorf("saved node file was modified by the conflicting batch")
1017		}
1018		// The legal new-node records must not have landed.
1019		for _, node := range []string{"乙", "丙"} {
1020			out, _, _ := historyCLI(t, dir, node)
1021			if strings.TrimRight(out, "\n") != "node="+node+" no heartbeats" {
1022				t.Errorf("node %q must have no records after rejected batch, got %q", node, out)
1023			}
1024			if _, err := os.Stat(nodeFileHexPath(dir, node)); !os.IsNotExist(err) {
1025				t.Errorf("no file may be created for node %q, stat err=%v", node, err)
1026			}
1027		}
1028	
1029		// After the conflict failure, a non-conflicting batch succeeds normally,
1030		// including a genuine new seq for 甲 and the previously rejected node.
1031		out, errOut, code = submit(t, dir, `[
1032		  {"node":"甲","seq":2,"collected_at":"2026-10-01T11:59:40Z","version":"1.26.0","height":102,"missed":0},
1033		  {"node":"乙","seq":1,"collected_at":"2026-10-01T11:59:10Z","version":"1.0","height":200,"missed":1}
1034		]`)
1035		if code != 0 {
1036			t.Fatalf("legal batch after a conflict failure must still succeed: exit=%d stderr=%q", code, errOut)
1037		}
1038		if strings.TrimRight(out, "\n") != "submitted: new=2 duplicate=0" {
1039			t.Errorf("recovery submit stdout=%q, want new=2 duplicate=0", out)
1040		}
1041	
1042		// 甲 keeps the original seq-1 content (not the conflict's) and gains the
1043		// new seq 2, ascending.
1044		jia := historyLines(t, dir, "甲")
1045		if len(jia) != 2 {
1046			t.Fatalf("甲 history = %q, want seq 1 and 2", jia)
1047		}
1048		if jia[0] != "node=甲 seq=1 collected_at=2026-10-01T11:59:00Z version=1.26.0 height=100 missed=0" {
1049			t.Errorf("original 甲 seq 1 telemetry altered: %q", jia[0])
1050		}
1051		if jia[1] != "node=甲 seq=2 collected_at=2026-10-01T11:59:40Z version=1.26.0 height=102 missed=0" {
1052			t.Errorf("new 甲 seq 2 line = %q", jia[1])
1053		}
1054	}
