	t.Helper()
	f := &fixture{t: t, dir: t.TempDir()}

	submitBatch(t, f.dir, `[
	  {"node":"mono","seq":1,"collected_at":"2026-10-01T11:59:57Z","version":"1.26.0","height":101,"missed":12},
