// validateCollectedAtFraction holds the single fractional-seconds precision
// rule for collected_at text: the saved instant is carried at nanosecond
// precision, so the fraction may have at most nine digits. More digits are
// accepted only when every digit past the ninth is zero — ".1234567890" is
// exactly ".123456789" — while any non-zero digit beyond the ninth would be
// silently truncated by time.Parse, merging distinct collection moments into
// one saved instant (two records a tenth of a nanosecond apart would dedup as
// one). Such input is rejected, never truncated or rounded.
func validateCollectedAtFraction(s string) error {
	body := s
	if strings.HasSuffix(body, "Z") {
		body = body[:len(body)-1]
	} else if len(body) >= 6 {
